<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Common\Application\Usecase\Install;

use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Shared\Connector\FileStorage\BinaryContent;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeWriteGateway;
use Civi\Lughauth\Features\Document\Theme\Domain\Theme;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeAttributes;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway\ThemeVersionWriteGateway;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersion;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionAttributes;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionChannelOptions;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetWriteGateway;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAsset;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAssetAttributes;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetContentVO;

/**
 * Installation step that seeds the default "corporate" UI themes used by the OAuth login
 * and consent screens.
 *
 * Three theme variants are created in a single install() call: "corporate" (the main
 * browser UI with responsive background images and slide-in animation), "corporate-full"
 * (a full-window layout used for profile and settings pages), and "corporate-mail" (a
 * table-based email layout for transactional notifications).
 *
 * Static CSS and image assets located in the assets/ directory are uploaded through the
 * ThemeAsset subsystem. Theme layout HTML is loaded from the contents/ directory. The mail
 * theme carries no binary assets. All themes are enabled immediately after creation so they
 * are ready for use as soon as the installation completes.
 */
class InstallCorporateTheme
{
    private const string STYLE_DIR = __DIR__ . '/assets/';
    private const string CONTENT_DIR = __DIR__ . '/contents/';

    public function __construct(
        private readonly ThemeWriteGateway $themes,
        private readonly ThemeVersionWriteGateway $versions,
        private readonly ThemeAssetWriteGateway $assets,
    ) {
    }

    /**
     * Creates and enables the "corporate", "corporate-full", and "corporate-mail" theme records
     * together with their respective layout HTML versions and static file assets.
     */
    public function install(): void
    {
        $this->installCorporateHtml();
        $this->installCorporateFullHtml();
        $this->installCorporateMail();
    }

    // -------------------------------------------------------------------------

    private function installCorporateHtml(): void
    {
        $theme = $this->createTheme('corporate');
        $layout = (string) file_get_contents(self::CONTENT_DIR . 'theme-corporate.html');
        $this->createVersion($theme, ThemeVersionChannelOptions::HTML, $layout);
        $this->installAssets($theme);
    }

    private function installCorporateMail(): void
    {
        $theme = $this->createTheme('corporate-mail');
        $layout = (string) file_get_contents(self::CONTENT_DIR . 'theme-corporate-mail.html');
        $this->createVersion($theme, ThemeVersionChannelOptions::MAIL, $layout);
    }

    private function installCorporateFullHtml(): void
    {
        $theme = $this->createTheme('corporate-full');
        $layout = (string) file_get_contents(self::CONTENT_DIR . 'theme-corporate-full.html');
        $this->createVersion($theme, ThemeVersionChannelOptions::HTML, $layout);
        $this->installAssets($theme);
    }

    // -------------------------------------------------------------------------

    private function createTheme(string $name): Theme
    {
        $attr = new ThemeAttributes();
        $attr->uid(Random::comb());
        $attr->name($name);
        $attr->isDefault(true);
        $attr->enabled(true);
        $created = $this->themes->create(Theme::create($attr));
        $this->themes->update($created, $created->enable());

        return $created;
    }

    private function createVersion(Theme $theme, ThemeVersionChannelOptions $channel, string $contentHtml): void
    {
        $attr = new ThemeVersionAttributes();
        $attr->uid(Random::comb());
        $attr->theme($theme);
        $attr->channel($channel);
        $attr->contentHtml($contentHtml);
        $this->versions->create(ThemeVersion::create($attr));
    }

    private function installAssets(Theme $theme): void
    {
        $styleDir = self::STYLE_DIR;

        if (!is_dir($styleDir)) {
            return;
        }

        $files = glob($styleDir . '*');
        foreach ($files !== false ? $files : [] as $filePath) {
            if (!is_file($filePath)) {
                continue;
            }
            $filename = basename($filePath);
            $binary   = BinaryContent::fromFile($filePath);
            $tempKey  = $this->assets->temporalStoreContent($binary);

            $attr = new ThemeAssetAttributes();
            $attr->uid(Random::comb());
            $attr->theme($theme);
            $attr->code($filename);
            $attr->type($binary->mime);
            $attr->content(ThemeAssetContentVO::fromTemporal($tempKey));
            $attr->enabled(true);

            $this->assets->create(ThemeAsset::create($attr));
            $this->assets->commitContent($tempKey);
        }
    }
}
